import type { APIRoute } from "astro";

// Prerendered alias of /sitemap-index.xml (generated by @astrojs/sitemap in astro.config.mjs; legacy URL set).
// Defining this route also stops EmDash from injecting its SSR /sitemap.xml, which static assets would never reach.
// robots.txt points crawlers at /sitemap-index.xml; this keeps /sitemap.xml working for tools that guess it.
export const prerender = true;

export const GET: APIRoute = ({ site }) => {
  const origin = (site ?? new URL("https://growgen.xyz")).origin;
  const xml = `<?xml version="1.0" encoding="UTF-8"?><sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><sitemap><loc>${origin}/sitemap-0.xml</loc></sitemap></sitemapindex>`;
  return new Response(xml, { headers: { "Content-Type": "application/xml; charset=utf-8" } });
};
